import type {
  AuthorityRule,
  CanonSource,
  InventoryItem,
  NormativeMarkdownAuditRecord,
  ReconciliationRecord,
} from './types.js'

/** Frozen source correspondence, not a grant or an execution receipt. */
export type R34Disposition = 'unchanged' | 'changed' | 'new' | 'retired'
export interface R34SourceMigration {
  readonly sourceId: string
  readonly disposition: R34Disposition
  readonly prior: Omit<CanonSource, 'inventoryItems'>
  readonly current: Omit<CanonSource, 'inventoryItems'>
  readonly priorItemOrder: readonly string[]
  readonly currentItemOrder: readonly string[]
}
export interface R34ItemMigration {
  readonly sourceId: string
  readonly itemId: string
  readonly disposition: R34Disposition
  readonly priorDigest: string | null
  readonly currentDigest: string | null
  readonly priorLocatorDigest: string | null
  readonly currentLocatorDigest: string | null
  readonly prior?: InventoryItem | null
  readonly current?: InventoryItem | null
  readonly replacementItemId?: string | null
}
export interface R34RuleMigration {
  readonly ruleId: string
  readonly disposition: R34Disposition
  readonly priorDigest: string | null
  readonly currentDigest: string | null
  readonly prior?: AuthorityRule | null
  readonly current?: AuthorityRule | null
}
export interface R34AuditMigration {
  readonly sourceId: string
  readonly itemId: string
  readonly disposition: R34Disposition
  readonly prior: NormativeMarkdownAuditRecord | null
  readonly current: NormativeMarkdownAuditRecord | null
}

